func buildClickHouseMasterDSNFromFields(userInfo, host string, port int, db string) string {
	if db == "" || host == "" {
		return ""
	}
	if port <= 0 {
		port = 9000
	}
	return fmt.Sprintf("clickhouse://%s%s:%d/%s?dial_timeout=5s&read_timeout=30s", userInfo, host, port, db)
}

